{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    allocations = [segment["minimum"] for segment in segments]
    remaining = budget - sum(allocations)

    while remaining > 0:
        eligible = [i for i, segment in enumerate(segments) if allocations[i] < segment["capacity"]]
        if not eligible:
            break
        weight_total = sum(segments[i]["importance"] for i in eligible)
        if weight_total <= 0:
            for i in eligible:
                if remaining <= 0:
                    break
                allocations[i] += 1
                remaining -= 1
            continue

        shares = [(i, remaining * segments[i]["importance"] / weight_total) for i in eligible]
        additions = [0] * len(segments)
        used = 0
        for i, share in shares:
            amount = min(segments[i]["capacity"] - allocations[i], int(share))
            additions[i] = amount
            used += amount
        if used:
            for i in eligible:
                allocations[i] += additions[i]
            remaining -= used
            if remaining <= 0:
                break

        ranked = sorted(
            eligible,
            key=lambda i: (-(remaining * segments[i]["importance"] / weight_total % 1), i),
        )
        assigned = 0
        for i in ranked:
            if remaining <= 0:
                break
            if allocations[i] < segments[i]["capacity"]:
                allocations[i] += 1
                remaining -= 1
                assigned += 1
        if not assigned and not used:
            break

    by_name = {segment["name"]: allocations[i] for i, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
